      const req = createMockRequest({
        'x-real-ip': '192.168.1.2'
      })

      const result = await limiter.checkLimit(req)
      expect(result.success).toBe(true)
    })

    it('extracts IP from cf-connecting-ip header', async () => {
      const req = createMockRequest({
        'cf-connecting-ip': '192.168.1.3'
      })

      const result = await limiter.checkLimit(req)
      expect(result.success).toBe(true)
    })

