      expect(response).toBeNull()
    })

    it('returns 429 response when limit exceeded', async () => {
      const req = createMockRequest({ 'x-forwarded-for': '192.168.1.1' })
      const middleware = limiter.middleware()

      // Exhaust the limit
      await limiter.checkLimit(req)
      await limiter.checkLimit(req)
      await limiter.checkLimit(req)

