      const req = createMockRequest({ 'x-forwarded-for': '192.168.1.1' })

      // Exhaust the limit
      await limiter.checkLimit(req)
      await limiter.checkLimit(req)
      await limiter.checkLimit(req)

      const failResult = await limiter.checkLimit(req)
      expect(failResult.success).toBe(false)

